<template>
  <section class="admin-page usage-page">
    <PageHeader title="成本与用量"><template #actions><t-button variant="outline" :loading="refreshing" :disabled="refreshing" @click="loadUsage(true)"><template #icon><i-refresh theme="outline" /></template>刷新</t-button></template></PageHeader>
    <div class="toolbar"><label v-if="isSuperAdmin"><span>分组</span><t-select v-model="filters.groupId" :options="groupOptions" @change="applyFilters" /></label><label><span>用户</span><t-select v-model="filters.ownerUserId" :options="userOptions" @change="applyFilters" /></label><label><span>任务类型</span><t-select v-model="filters.taskType" :options="taskTypeOptions" @change="applyFilters" /></label></div>
    <LoadingState v-if="loading" text="正在加载用量..." /><ErrorState v-else-if="loadError" :message="loadError" retryable @retry="loadUsage()" />
    <template v-else><section class="summary-strip" aria-label="用量汇总"><div><span>调用记录</span><strong>{{ result.summary.recordCount }}</strong></div><div><span>预估成本</span><strong>{{ formatMoney(result.summary.estimatedCost) }}</strong></div><div><span>计价口径</span><strong>内部预估</strong></div></section>
      <section class="data-section breakdown-section" aria-labelledby="breakdown-title"><div class="section-heading"><h2 id="breakdown-title">类型拆分</h2><span>{{ result.breakdown.length }} 类</span></div><EmptyState v-if="result.breakdown.length === 0" text="暂无用量拆分" /><div v-else class="breakdown-grid"><div v-for="item in result.breakdown" :key="item.taskType"><span>{{ taskTypeLabel(item.taskType) }}</span><strong>{{ formatMoney(item.estimatedCost) }}</strong><small>{{ item.recordCount }} 次</small></div></div></section>
      <section class="data-section" aria-labelledby="usage-title"><div class="section-heading"><h2 id="usage-title">用量记录</h2><span>共 {{ result.total }} 条</span></div><EmptyState v-if="result.items.length === 0" text="暂无符合条件的用量记录" /><div v-else class="table-scroll"><table><thead><tr><th>时间</th><th>分组</th><th>用户</th><th>项目</th><th>类型</th><th>Provider / 模型</th><th>预估成本</th><th>结果</th></tr></thead><tbody><tr v-for="item in result.items" :key="item.id"><td>{{ formatAdminDate(item.createdAt) }}</td><td>{{ item.groupName }}</td><td>{{ item.userName }}<small>#{{ item.userId }}</small></td><td>{{ item.projectName || "-" }}</td><td>{{ taskTypeLabel(item.taskType) }}</td><td>{{ item.providerId || "-" }}<small>{{ item.modelId || "-" }}</small></td><td>{{ item.estimatedCost === null ? "-" : formatMoney(item.estimatedCost) }} {{ item.currency || "" }}</td><td>{{ item.result === "succeeded" ? "成功" : item.result }}</td></tr></tbody></table></div><div v-if="result.total > pageSize" class="pagination" aria-label="用量分页"><t-button variant="outline" size="small" :disabled="page <= 1" @click="changePage(page - 1)">上一页</t-button><span>第 {{ page }} / {{ totalPages }} 页</span><t-button variant="outline" size="small" :disabled="page >= totalPages" @click="changePage(page + 1)">下一页</t-button></div></section>
    </template>
  </section>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from "vue"; import { storeToRefs } from "pinia"; import PageHeader from "../components/PageHeader.vue"; import LoadingState from "../components/LoadingState.vue"; import EmptyState from "../components/EmptyState.vue"; import ErrorState from "../components/ErrorState.vue"; import { formatAdminDate } from "../components/adminDate"; import { useAdminSessionStore } from "../session";
import { adminErrorText, getUsageOverview, listGroups, listUsers, type GroupDto, type UsageOverview, type UserDto } from "../api/adminApi";
const sessionStore = useAdminSessionStore(); const { session } = storeToRefs(sessionStore); const isSuperAdmin = computed(() => session.value?.role === "super_admin");
const result = ref<UsageOverview>({ summary: { recordCount: 0, estimatedCost: 0 }, breakdown: [], page: 1, pageSize: 20, total: 0, items: [] }); const groups = ref<GroupDto[]>([]); const users = ref<UserDto[]>([]); const loading = ref(true); const refreshing = ref(false); const loadError = ref(""); const page = ref(1); const pageSize = 20; let requestSequence = 0;
const filters = reactive<{ groupId: number | ""; ownerUserId: number | ""; taskType: string }>({ groupId: "", ownerUserId: "", taskType: "" });
const groupOptions = computed(() => [{ label: "全部分组", value: "" }, ...groups.value.map((group) => ({ label: group.name, value: group.id }))]); const userOptions = computed(() => [{ label: "全部用户", value: "" }, ...users.value.filter((user) => !filters.groupId || user.groupId === Number(filters.groupId)).map((user) => ({ label: `${user.name} (#${user.id})`, value: user.id }))]); const taskTypeOptions = [{ label: "全部类型", value: "" }, { label: "文本", value: "text" }, { label: "图片", value: "image" }, { label: "视频", value: "video" }]; const totalPages = computed(() => Math.max(1, Math.ceil(result.value.total / pageSize)));
const taskTypeLabels: Record<string, string> = { text: "文本", image: "图片", video: "视频" }; function taskTypeLabel(type: string) { return taskTypeLabels[type] || type; } function formatMoney(value: number) { return Number(value || 0).toFixed(6); }
async function loadTargets() { const [nextUsers, nextGroups] = await Promise.all([listUsers(), isSuperAdmin.value ? listGroups() : Promise.resolve([])]); users.value = nextUsers; groups.value = nextGroups; }
async function loadUsage(silent = false) { const sequence = ++requestSequence; if (silent) refreshing.value = true; else loading.value = true; loadError.value = ""; try { result.value = await getUsageOverview({ page: page.value, pageSize, ...(isSuperAdmin.value && filters.groupId ? { groupId: Number(filters.groupId) } : {}), ...(filters.ownerUserId ? { ownerUserId: Number(filters.ownerUserId) } : {}), ...(filters.taskType ? { taskType: filters.taskType } : {}) }); } catch (cause) { if (sequence === requestSequence) loadError.value = adminErrorText(cause, "用量加载失败"); } finally { if (sequence === requestSequence) { loading.value = false; refreshing.value = false; } } }
function applyFilters() { page.value = 1; void loadUsage(); } function changePage(nextPage: number) { page.value = nextPage; void loadUsage(); }
onMounted(async () => { try { await loadTargets(); await loadUsage(); } catch (cause) { loadError.value = adminErrorText(cause, "用量筛选项加载失败"); loading.value = false; } });
</script>

<style scoped lang="scss">
.admin-page { width: min(100%, 1320px); margin: 0 auto; }.toolbar { display: grid; grid-template-columns: repeat(3, minmax(170px, 260px)); gap: 8px; margin-bottom: 12px; }.toolbar label { display: grid; gap: 5px; color: var(--stars-text-muted); font-size: 12px; }.summary-strip { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); margin-bottom: 12px; border: 1px solid var(--stars-border); border-radius: 6px; background: #fff; }.summary-strip div { display: grid; gap: 5px; padding: 12px 14px; border-right: 1px solid var(--stars-border); }.summary-strip div:last-child { border-right: 0; }.summary-strip span { color: var(--stars-text-muted); font-size: 12px; }.summary-strip strong { font-size: 17px; font-variant-numeric: tabular-nums; }.data-section { margin-bottom: 12px; border: 1px solid var(--stars-border); border-radius: 6px; background: #fff; }.section-heading { display: flex; min-height: 42px; align-items: center; justify-content: space-between; padding: 8px 12px; border-bottom: 1px solid var(--stars-border); }.section-heading h2 { margin: 0; font-size: 14px; }.section-heading span { color: var(--stars-text-muted); font-size: 11px; }.breakdown-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); }.breakdown-grid div { display: grid; gap: 4px; padding: 10px 12px; border-right: 1px solid var(--stars-border); }.breakdown-grid div:last-child { border-right: 0; }.breakdown-grid span,.breakdown-grid small { color: var(--stars-text-muted); font-size: 11px; }.breakdown-grid strong { font-size: 14px; }.table-scroll { overflow-x: auto; } table { width: 100%; min-width: 1080px; border-collapse: collapse; font-size: 12px; } th { padding: 8px 10px; background: var(--stars-surface-muted); color: var(--stars-text-muted); font-weight: 600; text-align: left; white-space: nowrap; } td { padding: 8px 10px; border-top: 1px solid var(--stars-border); } td small { display: block; margin-top: 2px; color: var(--stars-text-muted); }.pagination { display: flex; align-items: center; justify-content: flex-end; gap: 10px; padding: 10px 12px; border-top: 1px solid var(--stars-border); color: var(--stars-text-muted); font-size: 12px; }
@media (max-width: 760px) { .toolbar,.summary-strip,.breakdown-grid { grid-template-columns: 1fr; }.summary-strip div,.breakdown-grid div { border-right: 0; border-bottom: 1px solid var(--stars-border); }.summary-strip div:last-child,.breakdown-grid div:last-child { border-bottom: 0; } }
</style>
